from textual.app import App, ComposeResult
from textual.containers import Vertical, Horizontal
from textual.widgets import Header, Button, Label, DataTable


class MyApp(App):
    CSS = """
        MyApp {
            align: center middle;
            #datatable { height: 1fr; }
            Horizontal { height: auto; }
            #button_row { align: center middle; }
            Button { margin: 1; height: auto; }
            #last_updated { dock: right; offset: 0 2; }
            Label { height: auto; }
        }
    """

    def compose(self) -> ComposeResult:
        self.last_updated = Label("Last Updated: NOW", id="last_updated")
        yield Header()
        yield Vertical(
            DataTable(id="datatable"),
            Horizontal(
                Button("OK", variant="primary", id="ok"),
                Button("Cancel", variant="error", id="cancel"),
                self.last_updated,
                id="button_row",
            ),
            id="main_tab",
        )

    def on_mount(self) -> None:
        rows = [
            ("Name", "Occupation", "Country"),
            ("Mike", "Python Wrangler", "USA"),
            ("Bill", "Engineer", "UK"),
            ("Dee", "Manager", "Germany"),
        ]
        table = self.query_one(DataTable)
        table.clear(columns=True)
        table.add_columns(*rows[0])
        table.add_rows(rows[1:])


if __name__ == "__main__":
    import asyncio

    async def main():
        app = MyApp()
        async with app.run_test(size=(80, 24)) as pilot:
            await pilot.pause()
            svg = app.export_screenshot()
            with open("/tmp/out.svg", "w") as f:
                f.write(svg)

    asyncio.run(main())
    print("done")

